import pages, runpy
from pages import reading as R
from fig2 import *
from fig import svg
E=pages.EXTRA
def lamps_row(n=7,w=440,y=0): return ''.join(f'<g transform="translate({(k+.5)*w/n-w/2} {y})">{lamp(["#c0392b","#e0a800","#1d6fb8"][k%3])}</g>' for k in range(n))
def F(label,items,labels=(),bg='#fffaf0',gy=160): return fig_row(label,items,labels,bg=bg,gy=gy)
LING='<path d="M-34 0 h68 l-8 -12 h-52z" fill="#8a8f9a"/><path d="M-14 -12 v-38 q14 -16 28 0 v38z" fill="#3a3a40"/>'
K='/festivals/kartika/'
E[K+'overview/']=[
 R('mahatmya','THE KĀRTIKA MĀHĀTMYA','What the texts say',F('A palm-leaf book with a lamp',[(book(),2),(lamp(),1.6)],['the Purāṇa','the lamp']),['<b>A whole praise-text.</b> The Skanda Purāṇa (Vaiṣṇava Khaṇḍa) and the Padma Purāṇa (Uttara Khaṇḍa) each contain a <b>Kārtika Māhātmya</b>, chapters praising the month, its bath, its lamps and its vows, with many stories of devotees blessed.','<b>Viṣṇu’s month.</b> These texts call Kārtika most dear to Viṣṇu, and say that even small acts (a lamp, a tulasī leaf, a dawn bath) carry great merit in it.','<b>Read in the month.</b> Many families read a chapter a day through Kārtika, as with the Devī Māhātmya in Navarātri.','<b>Stories inside.</b> They include the tales of Satyabhāmā, of Dharmadatta and the demoness Kalahā, and many others told to encourage the month’s practices.'],[('z','A whole book praising one month?'),('b','Two of them, in two Purāṇas. That tells you how highly the month was held.')],'The Kārtika Māhātmya: <b>a book in praise of the month</b>.'),
 R('dharmadatta','DHARMADATTA AND KALAHĀ','A Kārtika story',F('A brahmin sprinkling tulasī water on a ghostly woman',[(sage('#e0a800'),1.1),(tulasi(),1),(person('#8a8a9a'),1)],['Dharmadatta','tulasī water','Kalahā']),['<b>The meeting.</b> In a story of the Padma Purāṇa’s Kārtika Māhātmya, the pious brahmin <b>Dharmadatta</b>, on his way to a Kārtika lamp worship, met a terrifying spirit: <b>Kalahā</b>, a woman who had lived her life in quarrels and cruelty.','<b>Water with tulasī.</b> Frightened, he sprinkled her with water that held tulasī leaves, chanting Viṣṇu’s names.','<b>Memory returns.</b> At once her sins began to fall away, she remembered her past life, and she begged for release.','<b>Merit shared.</b> Dharmadatta gave her half the merit of his Kārtika vows, and she was freed. The story shows how far the month’s small practices reach.'],[('z','Half his merit to a ghost?'),('b','Like the Ekādaśī stories: the good done in Kārtika is meant to be shared.')],'A Kārtika vow <b>shared with a lost soul</b>.'),
 R('foods','FOOD IN KĀRTIKA','What many families avoid',F('A simple vegetarian plate',[('<ellipse rx="50" ry="12" fill="#5a8a3a" stroke="#111"/>'+''.join(f'<circle cx="{x}" cy="-6" r="7" fill="#fff"/>' for x in (-20,0,20)),1.6)],['simple food']),['<b>Simpler eating.</b> Many keep Kārtika vegetarian and simple; some give up onion, garlic, aubergine, or certain pulses for the month.','<b>One meal.</b> Some eat once a day, or avoid eating after sunset.','<b>Damodara’s offerings.</b> Vaiṣṇava households prepare sweets for Dāmodara, especially on Ekādaśīs and the full moon.','<b>Family rules.</b> These practices vary widely; they are vows chosen, not laws.'],[('z','Why give up particular vegetables?'),('b','Custom, and the idea of offering something you’d miss. The specific items differ by family.')],'Simple food <b>for a holy month</b>.'),
 R('karnataka','KĀRTIKA IN KARNATAKA','Lamps, temples and fairs',F('A temple courtyard lit with lamps and a fair outside',[(lamps:=lamp(),1.4),('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1),(person('#c0392b'),1)],['lamps','the temple','the fair']),['<b>Dīpotsavas.</b> Temples across the state hold lamp festivals in Kārtika, from small village shrines to great kṣetras ('+pages.link(2,'Part 3')+').','<b>Lakṣa Dīpotsava.</b> Dharmasthaḷa’s festival of a hundred thousand lamps draws visitors from across the state; see our <a href="/tulunadu/">Tulu Nadu collection</a>.','<b>Śiva and Viṣṇu.</b> Śiva temples are crowded on Kārtika Mondays; Viṣṇu temples keep Dāmodara worship and Tulasī Vivāha.','<b>At home.</b> The ākāśa dīpa on a pole and the evening lamp at the tulasī kaṭṭe are seen across old Mysuru.'],[('z','So Karnataka keeps both sides of Kārtika?'),('b','Both, fully: Śiva’s Mondays and Viṣṇu’s lamps.')],'Karnataka’s Kārtika: <b>lamps for Śiva and Viṣṇu alike</b>.')]
E[K+'somavara-lakshadipotsava/']=[
 R('somavrata','THE SOMAVĀRA VOW','Monday fasts for Śiva',F('A crescent moon over a liṅga with a devotee',[(moon(),1.6),(LING,1.2),(person('#c0392b'),1)],['Soma','the liṅga','the devotee']),['<b>All year, and especially now.</b> Many Śaivas fast on every Monday; in Kārtika the vow is kept with special care.','<b>The pattern.</b> A fast till evening, worship at a Śiva temple or at home, then a simple meal.','<b>Sixteen Mondays.</b> A popular vow (Solah Somavāra in the north) keeps sixteen Mondays in a row, often for a good marriage or family welfare.','<b>The moon’s story.</b> Monday honours Soma, the moon, whom Śiva saved from Dakṣa’s curse and wears in his hair.'],[('z','Why does Śiva wear the moon?'),('b','He sheltered the waning moon when it was cursed. Now it rests on his head, and Monday is his.')],'Mondays for the one <b>who wears the moon</b>.'),
 R('somnath','THE MOON’S CURSE','Why Monday is Śiva’s',F('A pale moon regaining its light beside a liṅga by the sea',[(moon(),2),(LING,1.3),(river(200,20),1)],['Soma','Somanātha','the sea']),['<b>Dakṣa’s daughters.</b> Soma married twenty-seven daughters of Dakṣa, the nakṣatras, but loved only Rohiṇī.','<b>The curse.</b> The others complained; Dakṣa cursed Soma to waste away.','<b>Śiva’s shelter.</b> Soma worshipped Śiva at Prabhāsa by the sea; Śiva softened the curse so that the moon wanes and waxes, and wore the crescent on his head.','<b>Somanātha.</b> That place became the first Jyotirliṅga, Somanātha; see our <a href="/temples-of-india/12-jyotirlingas/">Jyotirliṅga series</a>.'],[('z','So the moon’s phases come from a curse?'),('b','In the story, yes: a curse made bearable by Śiva. Waxing and waning is the moon’s second chance.')],'Śiva saved the moon: <b>Monday is his</b>.'),
 R('abhisheka','ABHIṢEKA ON KĀRTIKA MONDAYS','Bathing the liṅga',F('Milk being poured over a liṅga with bilva leaves',[(LING,1.6),(pot('#fff'),1)],['the liṅga','milk']),['<b>The main act.</b> On Kārtika Mondays Śiva temples perform long abhiṣekas with water, milk, curd, honey, ghee and tender coconut.','<b>Rudrābhiṣeka.</b> Where priests are trained, the <a href="/shiva/sri-rudram/">Śrī Rudram</a> is chanted during the bath.','<b>Families.</b> Families sponsor abhiṣekas for welfare, health or in memory of the departed.','<b>At home.</b> A small liṅga can be bathed with water and milk while chanting “namaḥ śivāya”.'],[('z','Why bathe Śiva so much?'),('b','He drank the poison and holds fire; devotees say he loves to be cooled. And bathing is the most intimate service.')],'Kārtika Mondays: <b>the liṅga bathed in milk</b>.'),
 R('dipotsava-how','HOW A DĪPOTSAVA IS LAID OUT','Lamps in patterns',F('Lamps arranged in the shape of a liṅga and a crescent',[(lamps_row(5,160),1),(moon(),2),(lamps_row(5,160),1)],['rows','a crescent','rows']),['<b>Patterns.</b> At many dīpotsavas lamps are laid out in shapes: the Oṃ, a liṅga, a trident, a crescent, or the name of the deity.','<b>Lit together.</b> At dusk volunteers light them from one flame passed hand to hand, until the whole pattern glows.','<b>Clay lamps.</b> Small clay lamps with ghee or oil and cotton wicks are traditional; temples now often ask for oil donations.','<b>Children.</b> Lighting lamps is a favourite part for children, a first experience of temple service.'],[('z','Can anyone light them?'),('b','Usually anyone who comes to help. That’s the joy of a dīpotsava.')],'One flame, passed hand to hand, <b>lights a thousand</b>.'),
 R('lamp-meaning','THE LAMP IN WORSHIP','Why light is the simplest offering',F('A single lamp',[(lamp(),3)],['dīpa']),['<b>In every pūjā.</b> A lamp (dīpa) is one of the sixteen services of every worship.','<b>What it means.</b> The flame stands for awareness; the oil for the self given up; the wick for the body; together, a life burning for God.','<b>A familiar verse.</b> Many households say a short prayer to the lamp at dusk, asking it to remove darkness and bring good fortune.','<b>Kārtika.</b> In this month the simplest offering becomes the central one.'],[('z','A lamp is a whole life?'),('b','That’s the reading: oil, wick and flame, slowly given. A beautiful image.')],'Oil, wick and flame: <b>a life offered</b>.')]
E[K+'karthigai-deepam/']=[
 R('bharani','THE DAWN BHARAṆĪ DĪPAM','The lamp before the great flame',F('Five lamps in a temple sanctum at dawn',[(lamps_row(5,200),1.2)],['five lamps']),['<b>Before dawn.</b> On the festival day at Tiruvaṇṇāmalai the <b>Bharaṇī Dīpam</b> is lit before the sanctum early in the morning, on the Bharaṇī star.','<b>Five flames.</b> A large lamp is lit and its flame used to light five lamps, often explained as Śiva’s five faces or the five elements.','<b>One again.</b> The five are later brought back into one: many and one, the theme of the day.','<b>Carried up.</b> That flame, tradition says, is what lights the great hilltop flame at dusk.'],[('z','The hill flame comes from the temple lamp?'),('b','That’s the beautiful link: dawn flame in the temple, dusk flame on the hill.')],'Five flames at dawn, <b>one on the hill at dusk</b>.'),
 R('ramana','RAMAṆA MAHARṢI AND ARUṆĀCALA','A modern saint of the hill',F('A sage seated in meditation at the foot of a hill',[('<path d="M-90 0 L0 -70 L90 0z" fill="#8a7a5a" stroke="#111" stroke-width="2"/>',1.3),(sage('#f4f1ea'),1)],['Aruṇācala','the sage']),['<b>Drawn to the hill.</b> Ramaṇa Maharṣi (1879–1950) came to Tiruvaṇṇāmalai as a youth and never left; he called Aruṇācala his guru and Śiva himself.','<b>Self-inquiry.</b> His teaching, “Who am I?”, drew seekers from around the world.','<b>Hymns to the hill.</b> He wrote devotional hymns to Aruṇācala in Tamil, sung at his āśrama.','<b>The Dīpam.</b> He watched the Kārttikai flame each year and spoke of it as the light of the Self.'],[('z','A modern saint worshipped the hill?'),('b','As his guru, the visible form of Śiva. For him the flame was the inner light made visible.')],'Ramaṇa: <b>the hill as guru</b>.'),
 R('girivalam','GIRIVALAM','Walking round the hill',F('Pilgrims walking barefoot round a hill under a full moon',[(person('#c0392b'),1),('<path d="M-90 0 L0 -70 L90 0z" fill="#8a7a5a" stroke="#111" stroke-width="2"/>',1.2),(person('#1d6fb8'),1)],['pilgrims','the hill','']),['<b>Pradakṣiṇa of a mountain.</b> Pilgrims walk clockwise round Aruṇācala, barefoot, often at night, chanting Śiva’s names.','<b>Full-moon nights.</b> Every full moon draws crowds; Kārttikai’s is the greatest.','<b>Shrines on the way.</b> The path passes eight Liṅga shrines for the eight directions (aṣṭa-liṅgas) and many smaller temples.','<b>Slowly.</b> Tradition says to walk slowly, like a pregnant queen, mindful of the hill.'],[('z','Like a pregnant queen?'),('b','A traditional image: walk gently, carefully, as if carrying something precious. You are walking round Śiva.')],'Walking round Śiva: <b>girivalam</b>.'),
 R('murugan','KĀRTTIKAI AND MURUGAN','The six mothers',F('Six small stars above a six-faced child on a lotus',[(''.join(f'<circle cx="{-40+k*16}" cy="-60" r="4" fill="#fff8d0" stroke="#111"/>' for k in range(6)),1.3),(child(),1.6)],['the Kṛttikās','Skanda']),['<b>The Kṛttikās.</b> The star cluster Kṛttikā (the Pleiades) is the six mothers who nursed baby Skanda, hence his name Kārttikeya.','<b>Murugan’s festival too.</b> Kārttikai Dīpam is also sacred to Murugan; Tamil Murugan temples light lamps that night.','<b>Śiva and son.</b> The night honours both: Śiva as light, Skanda as the child of that light.','<b>Our series.</b> See our <a href="/subramanya/">Subrahmaṇya series</a> and <a href="/festivals/navaratri/skandamata/">Skandamātā</a>.'],[('z','So Kārttikeya is named after these stars?'),('b','Exactly. The night of the Kṛttikā star is his night too.')],'The Kṛttikā stars: <b>Murugan’s mothers</b>.')]
E[K+'tulasi/']=[
 R('names','THE NAMES OF TULASĪ','Eight names',F('Eight leaves in a circle',[(''.join(f'<ellipse cx="{30*math.cos(a)}" cy="{30*math.sin(a)-30}" rx="7" ry="4" fill="#3a8a3a"/>' for a in [k*0.785 for k in range(8)]),2)],['eight names']),['<b>Eight names.</b> A popular hymn gives Tulasī eight names: Vṛndā, Vṛndāvanī, Viśvapūjitā, Viśvapāvanī, Puṣpasārā, Nandinī, Tulasī and Kṛṣṇajīvanī.','<b>Vṛndāvana.</b> Kṛṣṇa’s forest, Vṛndāvana, is “Vṛndā’s forest”, the forest of tulasī.','<b>Kṛṣṇajīvanī.</b> “Kṛṣṇa’s life”: she is so dear to him.','<b>In daily prayer.</b> Many recite these names while circling the plant.'],[('z','Vṛndāvana is named after tulasī?'),('b','In the tradition, yes: the forest where she grows thick, where Kṛṣṇa played.')],'Vṛndā, Vṛndāvanī… <b>Kṛṣṇa’s life</b>.'),
 R('kattè','THE TULASĪ KAṬṬE','The pedestal in the courtyard',F('A square pedestal with a niche for a lamp and a tulasī on top',[(tulasi(),2.2)],['tulasī kaṭṭe']),['<b>The structure.</b> The tulasī kaṭṭe (Kannada), tulasī māḍam (Tamil) or tulasī vṛndāvan is a raised square pedestal, often with a small niche for a lamp and carvings of deities.','<b>Facing east.</b> It usually stands in the centre of the courtyard or in front of the house.','<b>Decorated.</b> It is painted with rangoli, turmeric and kuṅkuma, and decorated for festivals.','<b>Flats and balconies.</b> In city homes a pot on the balcony serves the same purpose.'],[('z','A balcony pot counts?'),('b','Of course. The goddess lives where she is loved, not where there’s a courtyard.')],'A pedestal or a pot: <b>Tulasī’s home</b>.'),
 R('shaligrama','THE ŚĀLAGRĀMA','Viṣṇu as a stone',F('Black round stones with spiral fossil marks',[('<ellipse rx="22" ry="18" fill="#2a2a3a" stroke="#111" stroke-width="2"/><path d="M-8 -2 q8 -10 16 0 q-8 8 -16 0" fill="none" stroke="#888" stroke-width="2"/>',2),('<ellipse rx="18" ry="15" fill="#2a2a3a" stroke="#111" stroke-width="2"/>',1.6)],['śālagrāma','']),['<b>What it is.</b> A śālagrāma is a smooth black stone, usually an ammonite fossil, from the Gaṇḍakī river in Nepal, worshipped as Viṣṇu.','<b>No consecration needed.</b> Unlike images, a śālagrāma is held to be Viṣṇu already, without a consecration rite.','<b>With tulasī.</b> Śālagrāma and tulasī are worshipped together; Tulasī Vivāha marries them ('+pages.link(5,'Part 6')+').','<b>The curse turned blessing.</b> In the Vṛndā story, her curse made Viṣṇu a stone; the stone is now his most intimate form.'],[('z','A fossil is Viṣṇu?'),('b','So the tradition holds: ancient life turned to stone, now a home for the Lord.')],'The śālagrāma: <b>Viṣṇu in a river stone</b>.'),
 R('prayer','THE TULASĪ PRAYER','What families say',F('A woman with folded hands circling the tulasī',[(person('#c0392b'),1.2),(tulasi(),1.6),(lamp(),1.2)],['','tulasī','']),['<b>When circling.</b> As they walk round the plant, many say a short prayer praising tulasī as the one at whose root are all holy places, in whose middle are all gods, and at whose top are all the Vedas.','<b>Asking for good.</b> Women traditionally pray for the family’s welfare and for an auspicious married life.','<b>Picking leaves.</b> Before plucking, many ask permission with a prayer.','<b>Simple.</b> Even a silent bow at the plant is a prayer.'],[('z','Ask a plant’s permission?'),('b','A goddess’s permission. It’s a lovely habit: take nothing without asking.')],'A bow at the plant, <b>a prayer for the home</b>.')]
E[K+'prabodhini-tulasi-vivaha/']=[
 R('chaturmasya-end','THE END OF CĀTURMĀSYA','Four months completed',F('Four rain clouds giving way to sun',[('<path d="M-40 0 q0 -20 20 -20 q10 -20 30 -10 q20 -10 30 10 q10 10 0 20z" fill="#dfe9f6" stroke="#111" stroke-width="2"/>',1),(sun(20),1)],['the rains','the sun returns']),['<b>Vows completed.</b> Those who took Cāturmāsya vows on Devaśayanī Ekādaśī complete them now, often with an udyāpana worship and feeding.','<b>Foods return.</b> Foods given up for the months return to the table.','<b>Ascetics travel.</b> Sannyāsins, who stayed in one place, may move again; see our <a href="/festivals/guru-purnima/chaturmasya/">Cāturmāsya article</a>.','<b>The season turns.</b> The rains are over, the harvest is in, and the festive season of weddings begins.'],[('z','So Prabodhinī is a big “end of term”?'),('b','For four months of vows, yes. And the start of the happiest season.')],'Four months of vows <b>completed</b>.'),
 R('wedding-songs','THE WEDDING SONGS','What is sung',F('Women singing beside the tulasī bride',[(person('#c0392b'),1),(tulasi(),1.4),(person('#e0a800'),1)],['','the bride','']),['<b>Wedding songs.</b> Women sing the same songs sung at human weddings: welcoming the groom, blessing the bride, teasing the in-laws.','<b>Kṛṣṇa songs.</b> Songs about Kṛṣṇa and Rukmiṇī, or Kṛṣṇa and Tulasī, are popular.','<b>Regional.</b> In Maharashtra, maṅgalāṣṭakas (wedding verses) are recited; in Karnataka, devotional songs in Kannada.','<b>Joy.</b> The mood is a real wedding: laughter, sweets and music.'],[('z','They tease the groom’s family?'),('b','Just like a real wedding! That’s how you know families take this marriage to heart.')],'Wedding songs <b>for Tulasī</b>.'),
 R('meaning','WHY MARRY A PLANT?','The meaning of Tulasī Vivāha',F('A tulasī and a śālagrāma joined by a garland',[(tulasi(),1.4),('<path d="M-60 -40 q60 30 120 0" fill="none" stroke="#e0a800" stroke-width="4"/>',1),('<ellipse rx="16" ry="12" fill="#2a2a3a"/>',1.4)],['Tulasī','','Viṣṇu']),['<b>Love honoured.</b> It completes the Vṛndā story: the faithful woman wronged becomes Viṣṇu’s beloved bride.','<b>The divine in the everyday.</b> It brings the Lord and the Goddess into the courtyard, among ordinary plants and stones.','<b>The wedding season.</b> Before the community marries its children, it marries the Lord.','<b>A gift for the childless.</b> Couples without daughters find in it the joy of giving away a bride.'],[('z','It’s not just pretend?'),('b','For devotees it is a real wedding of the Lord and Goddess, in forms they can hold.')],'The Lord and Goddess <b>married in the courtyard</b>.'),
 R('pandharpur','KĀRTIKĪ EKĀDAŚĪ AT PAṆḌHARPŪR','Maharashtra’s great day',F('Pilgrims with flags walking toward a temple',[(person('#ff8c1a'),1),(flag(),1),('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1)],['vārkarī','','Viṭṭhala']),['<b>Viṭṭhala.</b> At Paṇḍharpūr, Viṭṭhala (Viṣṇu as Kṛṣṇa) stands on a brick with hands on his hips; he is the deity of Maharashtra’s vārkarī saints.','<b>Two great Ekādaśīs.</b> Āṣāḍhī (Devaśayanī) and Kārtikī (Prabodhinī) Ekādaśī bring huge pilgrimages.','<b>Saints.</b> Jñāneśvar, Tukārām and Nāmdev sang of Viṭṭhala; Purandara Dāsa of Karnataka also sang of “Paṇḍharapura Viṭhala”.','<b>Karnataka link.</b> Viṭṭhala is beloved in North Karnataka too; Hampi’s great Viṭṭhala temple honours him.'],[('z','Purandara Dāsa sang to Viṭṭhala?'),('b','His mudrā, his poetic signature, is “Purandara Viṭṭhala”. Karnataka and Maharashtra share this Lord.')],'Paṇḍharpūr’s Viṭṭhala: <b>Karnataka’s too</b>.')]
E[K+'kartika-purnima/']=[
 R('pushkar','THE PUṢKAR FAIR','Brahmā’s lake',F('A lake with ghāṭs and camels',[(river(200,30),1),(beast('donkey','#c9a46a'),1)],['the lake','camels']),['<b>Brahmā’s lake.</b> Puṣkar in Rajasthan has one of the very few temples of Brahmā and a sacred lake.','<b>Bathing.</b> Bathing in the lake on Kārtika Pūrṇimā is held especially holy.','<b>The fair.</b> The Puṣkar fair around the full moon is famous for its camel and livestock trading.','<b>Pilgrims and traders.</b> Devotion and commerce together, as at many old Indian fairs.'],[('z','A camel fair on a holy day?'),('b','Old India mixed pilgrimage and trade naturally. The lake is the reason; the fair grew around it.')],'Puṣkar: <b>Brahmā’s lake and a great fair</b>.'),
 R('boita','BOITA BANDĀṆA','Odisha’s paper boats',F('Little boats with lamps floating on water',[(river(200,60),1),(boat_lamp(),2),(boat_lamp(),2)],['','boats','']),['<b>Ancient voyages.</b> In Odisha, Kārtika Pūrṇimā remembers the sādhabas, merchants who sailed to Bali and Java in the old days.','<b>Boats at dawn.</b> Before dawn, people float little boats of banana bark or paper with lamps on rivers and ponds.','<b>Bali Yātrā.</b> A great fair at Cuttack, Bali Yātrā, celebrates this maritime past.','<b>A link to the sea.</b> Lamps on water: Kārtika’s light carried outward.'],[('z','Merchants sailing to Bali?'),('b','Odisha’s ancient seafarers did. The festival remembers them with tiny boats.')],'Tiny boats, <b>ancient voyages</b>.'),
 R('vow-complete','COMPLETING THE MONTH’S VOWS','Udyāpana',F('A family feeding guests at the end of a vow',[(person('#c0392b'),1),('<ellipse rx="40" ry="10" fill="#5a8a3a" stroke="#111"/>',1.4),(sage('#e0a800'),1)],['host','','guest']),['<b>Udyāpana.</b> A vow kept for the month is closed with an udyāpana: a final worship, often a homa, and feeding guests or brahmins.','<b>Gifts.</b> Lamps, cloth, food and dakṣiṇā are given.','<b>For lamp vows.</b> Those who lit lamps all month may give lamps to a temple.','<b>Gratitude.</b> The closing is thanksgiving for having kept the month.'],[('z','Every vow needs a closing?'),('b','A good vow has a beginning, middle and end. The udyāpana is the end.')],'Every vow <b>completed with thanks</b>.'),
 R('meaning','THE MONTH IN ONE THOUGHT','Light in the dark season',F('A single lamp in darkness',[(lamp(),3)],['light'],bg='#2a2a3a'),['<b>The dark half of the year.</b> Kārtika comes as nights lengthen and winter approaches.','<b>Answer with light.</b> Its whole practice is light: lamps at dusk, the dawn bath, the flame on Aruṇācala, the ghāṭs of Kāśī.','<b>Both gods.</b> Viṣṇu as Dāmodara, Śiva as the column of fire: the same light.','<b>Carry it on.</b> The tradition hopes one small habit (an evening lamp) continues through the year.'],[('z','So Kārtika is about light?'),('b','In one word, yes. The rest is detail.')],'Kārtika in one word: <b>light</b>.')]
P='/festivals/pitru-paksha/'
E[P+'overview/']=[
 R('history','AN ANCIENT PRACTICE','From the Veda to today',F('An ancient fire altar and a modern family',[(flames(),1.3),(person('#f4f1ea',seat=True),1)],['Vedic rite','today']),['<b>Vedic roots.</b> Offerings to the fathers (pitṛs) appear in the Ṛg Veda, which has hymns to them, and in the Gṛhya Sūtras, which describe the rites.','<b>The Purāṇas.</b> The Garuḍa, Viṣṇu and Matsya Purāṇas detail śrāddha and the special merit of the dark fortnight before Navarātri.','<b>Across India.</b> Every region keeps Pitṛ Pakṣa, with local names and customs.','<b>Across faiths.</b> Many cultures set aside days for ancestors; Pitṛ Pakṣa is India’s great one.'],[('z','The Ṛg Veda has hymns to ancestors?'),('b','Yes, to the pitṛs. Remembering ancestors is among the oldest Indian practices.')],'From the Veda to today: <b>remembering the fathers</b>.'),
 R('women','WOMEN AND PITṚ PAKṢA','Mothers remembered',F('A mother and daughter offering water',[(person('#c0392b'),1.1),(pot('#c9a24a'),1),(person('#e0a800'),1)],['','','']),['<b>Avidhavā Navamī.</b> The ninth day of the fortnight is set aside in many traditions for married women who died before their husbands (sumaṅgalīs), and for mothers.','<b>Mātāmaha.</b> Many rites include the maternal line (mother’s father and forebears) alongside the paternal.','<b>Women performing.</b> Practice is changing: many families now have daughters perform śrāddha.','<b>Feeding sumaṅgalīs.</b> Some families feed married women on Navamī in memory of a mother.'],[('z','There’s a day just for mothers?'),('b','Navamī, in many traditions. The fortnight remembers both lines.')],'Navamī: <b>a day for mothers</b>.'),
 R('dana','GIVING IN THE FORTNIGHT','Dāna',F('Gifts of grain, cloth and a lamp',[(pot('#e0a800'),1.2),('<rect x="-20" y="-20" width="40" height="20" fill="#c0392b" stroke="#111"/>',1.4),(lamp(),1.2)],['grain','cloth','lamp']),['<b>Giving on their behalf.</b> Gifts made in the fortnight are made in the ancestors’ names.','<b>What.</b> Food grains, cloth, sesame, a cow (in the old texts), utensils, or money to the needy.','<b>Feeding.</b> Feeding the hungry is the most praised gift.','<b>Today.</b> Many give to charities, orphanages or old-age homes in their parents’ memory.'],[('z','Can I donate to a charity instead?'),('b','Many do: it is giving in their name. The tradition praises feeding most of all.')],'Giving <b>in their name</b>.'),
 R('remember','REMEMBERING WELL','Beyond the rite',F('A family looking at old photographs by a lamp',[(person('#c0392b',seat=True),1),('<rect x="-20" y="-30" width="40" height="30" fill="#fff" stroke="#111"/>',1.4),(child(),1.2)],['','photos','']),['<b>Stories.</b> Many families use the fortnight to tell children about grandparents and great-grandparents.','<b>Names.</b> Saying the names in the rite keeps three generations alive in memory.','<b>Their values.</b> Remembering what they stood for is a way of honouring them.','<b>A family tree.</b> Some families write down their gotra and the names of ancestors for the next generation.'],[('z','So I should learn my great-grandparents’ names?'),('b','The rite asks for them. Ask your elders before the names are lost.')],'Tell the children <b>who came before</b>.')]
E[P+'shraddha-tarpana/']=[
 R('preparation','PREPARING FOR ŚRĀDDHA','The day before and the morning',F('A clean kitchen and a priest invited',[('<rect x="-30" y="-40" width="60" height="40" fill="#f3e3c3" stroke="#111"/>',1.2),(sage('#f4f1ea'),1)],['the kitchen','the priest']),['<b>Purity.</b> The house is cleaned, and the cook and performer observe restraint the day before.','<b>The priest.</b> A family priest is engaged to guide the rite according to the family’s Veda and tradition.','<b>The food.</b> Special dishes are cooked fresh; certain items (black gram, sesame, honey) are traditional, others avoided.','<b>The time.</b> Śrāddha is usually performed around midday (aparāhṇa), the time said to be the ancestors’.'],[('z','Why midday?'),('b','The texts set the afternoon for the ancestors, as the morning is for the gods.')],'Clean, prepare, <b>at midday</b>.'),
 R('darbha','DARBHA GRASS','Why kuśa',F('Blades of darbha grass and a ring made from them',[('<path d="M-6 0 q-4 -40 4 -60 M0 0 q2 -40 -2 -60 M6 0 q4 -40 -4 -60" stroke="#5a8a3a" stroke-width="3" fill="none"/>',2),('<circle r="12" fill="none" stroke="#5a8a3a" stroke-width="4"/>',2)],['darbha','pavitra']),['<b>Sacred grass.</b> Darbha (kuśa) has been used in Vedic ritual for three thousand years.','<b>Purity.</b> It is held to purify and to protect the rite; a ring of it, the pavitra, is worn.','<b>A seat.</b> Darbha is spread as a seat for the ancestors and the piṇḍas.','<b>A story.</b> The Purāṇas say darbha was touched by the nectar of immortality when Garuḍa set it down.'],[('z','Nectar touched the grass?'),('b','So the story says, when Garuḍa brought amṛta to free his mother. Ever since, darbha is pure.')],'Darbha: <b>the grass touched by nectar</b>.'),
 R('sesame','BLACK SESAME','The ancestors’ seed',F('A bowl of black sesame seeds',[('<ellipse rx="40" ry="14" fill="#2a2a3a" stroke="#111" stroke-width="2"/>',1.6)],['tila']),['<b>For the pitṛs.</b> Black sesame (tila) is used in nearly every ancestral rite.','<b>A story.</b> One tradition says sesame arose from Viṣṇu’s sweat; another that it is dear to Yama.','<b>Purifying.</b> It is said to drive away evil spirits from the rite.','<b>Not in god-rites.</b> Black sesame is generally not used in the worship of gods, marking the difference.'],[('z','Why black sesame and not white?'),('b','Black for the ancestors, by tradition. White sesame is used in festive foods.')],'Black sesame: <b>the seed of the ancestors</b>.'),
 R('mantras','WORDS OF THE RITE','What is said',F('A priest speaking while water is poured',[(sage('#f4f1ea'),1.1),(pot('#c9a24a'),1)],['priest','']),['<b>Names and gotra.</b> The rite names each ancestor with their gotra (lineage) and relationship.','<b>Svadhā.</b> Offerings to the ancestors end with <i>svadhā</i>, as offerings to gods end with <i>svāhā</i>.','<b>Vedic verses.</b> Verses from the Veda addressed to the pitṛs are recited.','<b>Your own words.</b> Many also add a simple personal prayer for the departed.'],[('z','Svadhā instead of svāhā?'),('b','The ancestors’ own word. You hear it and know: this offering is for the fathers.')],'<b>Svadhā</b>: the ancestors’ word.')]
E[P+'mahalaya-amavasya/']=[
 R('rivers','RIVERS ON MAHĀLAYA','Where people gather',F('Crowds offering water at a river at dawn',[(river(200,40),1),(person('#f4f1ea'),1),(person('#f4f1ea'),1)],['the river','','']),['<b>Holy rivers.</b> The Gaṅgā, Godāvarī, Kāverī, Narmadā and other rivers see huge crowds on Mahālaya dawn.','<b>Temples by water.</b> Temple tanks and seashores (Rāmeśvaram, Gokarṇa) also host the rites.','<b>Priests on the banks.</b> Priests sit on the banks guiding families through tarpaṇa.','<b>Personal too.</b> Many simply offer water at home, facing south.'],[('z','Can I do it at home?'),('b','Yes. Water, sesame and the names, said with love, facing south.')],'River banks crowded <b>at Mahālaya dawn</b>.'),
 R('forgotten','FOR THOSE WITH NO ONE','A rite for the forgotten',F('Water offered toward the sky for unknown souls',[(person('#f4f1ea'),1.2),('<path d="M0 -40 q20 -40 0 -80" stroke="#8fb8de" stroke-width="3" fill="none"/>',1)],['','']),['<b>A special offering.</b> On Mahālaya many offer tarpaṇa for all who died with no one to remember them: those without children, those lost in accidents, wars or disasters.','<b>Friends and teachers.</b> Others offer for friends, teachers, and even animals they loved.','<b>Universal.</b> The rite widens from family to all beings.','<b>Compassion.</b> Many find this the most moving part of the fortnight.'],[('z','Even pets?'),('b','Some families do. The rite’s heart is gratitude and compassion.')],'A handful of water <b>for those with no one</b>.'),
 R('crows-day','THE CROWS ON MAHĀLAYA','Waiting for a sign',F('A crow on a wall above a leaf with rice',[(crow(),2),(piNDa(),1.4)],['','']),['<b>The last day.</b> On Mahālaya the food offering for crows is especially important.','<b>The sign.</b> Families wait; a crow eating is taken as a sign the ancestors are satisfied.','<b>Patience.</b> If none comes, families feed a cow or put the food in water.','<b>Symbol.</b> The crow’s visit closes the fortnight on a hopeful note.'],[('z','What if no crow comes?'),('b','Feed a cow or another creature. The offering is never wasted.')],'A crow at the leaf: <b>the fortnight closes</b>.'),
 R('transition','FROM ANCESTORS TO THE MOTHER','The turn of the season',F('A dark moon turning into a bright lamp for the Goddess',[('<circle r="24" fill="#2a2a3a" stroke="#111" stroke-width="2"/>',1.4),(lamp(),1.6),(devi(items=('trident','lotus')),1)],['new moon','','Navarātri']),['<b>Darkness to light.</b> The new moon of Mahālaya is the darkest night; the next morning Navarātri begins with the waxing moon.','<b>Gratitude to celebration.</b> The fortnight of looking back opens into nine nights of the Mother.','<b>Mahālaya’s name.</b> Mahālaya can be read as “the great abode”: the time when the ancestors visit, and when the Goddess is invited.','<b>Our series.</b> See <a href="/festivals/navaratri/starting-the-nine-nights/">Starting the Nine Nights</a>.'],[('z','The calendar is beautifully arranged.'),('b','Remember, then rejoice. That is how the year turns here.')],'From remembrance <b>to the Mother’s nights</b>.'),
 R('poems','MAHĀLAYA IN BENGAL’S MEMORY','A dawn people wait for',F('A radio on a windowsill at dawn',[('<rect x="-30" y="-24" width="60" height="30" rx="4" fill="#a8553a" stroke="#111" stroke-width="2"/><circle cx="-12" cy="-9" r="7" fill="#e8c06a"/>',2)],['the dawn broadcast']),['<b>The broadcast.</b> For generations Bengali families have woken before dawn on Mahālaya to the radio programme of Caṇḍī recitation and songs.','<b>A shared memory.</b> For many, Mahālaya means that voice, that hour and the smell of the season.','<b>Tarpaṇa after.</b> Then men go to the river for tarpaṇa.','<b>The images.</b> Artisans paint the Goddess’s eyes; the countdown to Durgā Pūjā begins.'],[('z','A radio programme is a tradition?'),('b','For Bengal, a beloved one. Traditions are made of such things too.')],'Bengal’s Mahālaya: <b>the voice before dawn</b>.')]
E[P+'places/']=[
 R('badri','BRAHMA KAPĀLA AT BADRĪNĀTH','The Himalayan place of offering',F('A rock platform by a rushing river below snow peaks',[(mountain(),1.2),(river(200,30),1)],['Himālaya','Alakanandā']),['<b>On the Alakanandā.</b> At Badrīnāth, the <b>Brahma Kapāla</b> ghāṭ on the Alakanandā river is a famous place for śrāddha.','<b>Final offering.</b> Some traditions say offering piṇḍa here frees the ancestors completely.','<b>The story.</b> The name links to Brahmā’s skull, which fell here from Śiva’s hand.','<b>Char Dhām.</b> See our <a href="/temples-of-india/char-dham/">Char Dhām series</a>.'],[('z','Śiva had Brahmā’s skull in his hand?'),('b','A Purāṇic story: it stuck to his hand until it fell at this holy place.')],'Badrīnāth’s <b>Brahma Kapāla</b>.'),
 R('rameshvaram','RĀMEŚVARAM AND THE SEA','Tīrtha baths and offerings',F('Waves at a temple shore',[(river(200,40,'#5a8ac0'),1),('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1)],['the sea','Rāmanāthasvāmī']),['<b>Rāma’s place.</b> Rāmeśvaram, where Rāma worshipped Śiva, is a major place of ancestral rites, at the sea (Agni Tīrtham).','<b>Twenty-two wells.</b> Pilgrims bathe in the temple’s sacred wells before worship.','<b>A pair.</b> Many families combine Kāśī and Rāmeśvaram in one lifetime’s pilgrimage.','<b>Our series.</b> See our <a href="/temples-of-india/12-jyotirlingas/">Jyotirliṅga series</a>.'],[('z','Kāśī and Rāmeśvaram together?'),('b','North and south: a traditional pairing. Pilgrims carry Gaṅgā water to Rāmeśvaram.')],'Rāmeśvaram: <b>offerings at the sea</b>.'),
 R('gokarna','GOKARṆA','Karnataka’s coast',F('A temple near a beach',[(river(200,40,'#5a8ac0'),1),('<path d="M-40 0 h80 l-12 -90 h-56z" fill="#e8c06a" stroke="#111" stroke-width="2"/>',1)],['the sea','Mahābaleśvara']),['<b>Mahābaleśvara.</b> Gokarṇa’s Ātmaliṅga temple on the coast is a major Karnataka pilgrimage.','<b>Ancestral rites.</b> Families come for śrāddha and the immersion of ashes at the sea.','<b>Kāśī of the south.</b> Gokarṇa is sometimes called Dakṣiṇa Kāśī.','<b>Our article.</b> See <a href="/temples-of-india/karnataka/gokarna/">Gokarṇa</a>.'],[('z','Another “Kāśī of the south”?'),('b','Several places claim the title. Gokarṇa’s claim is ancient.')],'Gokarṇa: <b>the coast’s Kāśī</b>.'),
 R('home-anywhere','ANYWHERE WITH FAITH','When you cannot travel',F('A family offering water at home facing south',[(person('#f4f1ea'),1),(pot('#c9a24a'),1),(person('#c0392b'),1)],['','','']),['<b>Faith first.</b> The texts say the power of śrāddha is in śraddhā, faith. The rite at home is complete.','<b>Facing south.</b> At home, face south, the ancestors’ direction.','<b>Local temples.</b> Many temples offer śrāddha arrangements for families.','<b>Pilgrimage when possible.</b> The holy places add devotion; they are not required.'],[('z','So Gayā is not compulsory?'),('b','It is highly praised, not compulsory. Love at home reaches the ancestors too.')],'Any place, <b>with faith</b>.')]
E[P+'after-death/']=[
 R('antyeshti','THE LAST RITES','Antyeṣṭi',F('A lamp and flowers by a covered body',[(lamp(),1.6),('<rect x="-50" y="-14" width="100" height="14" fill="#f4f1ea" stroke="#111"/>',1.4)],['','']),['<b>The last sacrifice.</b> Antyeṣṭi, “the last offering”, is the funeral rite: the body is offered to Agni.','<b>Ten days.</b> Over the next ten days piṇḍas are offered daily, said to build the subtle body.','<b>Twelfth and thirteenth days.</b> Rites on the 11th–13th days complete the first stage; the family then returns to normal life.','<b>A shape for grief.</b> The rites give mourners clear tasks in the hardest days.'],[('z','Why so many days of rites?'),('b','The tradition says the departed needs them; the family needs them too.')],'Antyeṣṭi: <b>the last offering</b>.'),
 R('upanishad','THE UPANIṢADS ON DEATH','Naciketas and Yama',F('A boy facing Yama at the door',[(child(),1.6),(god('#2a2a3a'),1.2)],['Naciketas','Yama']),['<b>Naciketas.</b> In the Kaṭha Upaniṣad the boy Naciketas goes to Yama, god of death, and asks what happens after death.','<b>Yama’s teaching.</b> Yama teaches that the Self is never born and never dies; the wise, knowing it, go beyond death.','<b>Two paths.</b> The Upaniṣads also speak of the path of the ancestors (pitṛyāna) and the path of the gods (devayāna).','<b>Read more.</b> The Gītā’s verses echo the Kaṭha closely.'],[('z','A boy argued with Death?'),('b','And Death taught him. The Kaṭha Upaniṣad is one of the great texts on dying.')],'Naciketas and Yama: <b>the oldest conversation about death</b>.'),
 R('grief','GRIEF AND THE TRADITION','Comfort for the living',F('A family seated together by a lamp',[(person('#c0392b',seat=True),1),(lamp(),1.2),(person('#1d6fb8',seat=True),1)],['','','']),['<b>Grief is human.</b> The tradition does not ask mourners to feel nothing; the rites themselves are full of tears.','<b>Community.</b> Relatives and friends visit, cook and sit with the family in the first days.','<b>Each year.</b> The annual śrāddha and Pitṛ Pakṣa give grief a place to return to, year after year.','<b>Hope.</b> The teaching of the undying Self is offered as comfort, not as a command to stop grieving.'],[('z','So it’s okay to cry?'),('b','Of course. Even Rāma wept for his father. The tradition holds grief, it doesn’t forbid it.')],'Grief <b>held, not forbidden</b>.'),
 R('names','THE DIVINE NAME AT THE END','Why we chant at the bedside',F('A family chanting at the bedside of an elderly person',[(person('#8a8a8a'),1),(book(),1.2),(person('#c0392b'),1)],['','','']),['<b>Gītā 8.5.</b> Whoever leaves the body remembering God reaches him.','<b>At the bedside.</b> Families chant God’s names, play hymns, or place tulasī and Gaṅgā water near the dying.','<b>A lifetime’s practice.</b> The tradition teaches that the last thought follows one’s habits; so the practice begins long before.','<b>Peace.</b> The sound of familiar names comforts both the dying and the family.'],[('z','So we practise now for then?'),('b','That is the old teaching: remember God daily, and you will at the end.')],'The name at the end, <b>practised all life</b>.')]
runpy.run_path('kartika.py'); runpy.run_path('pitru.py')
print('extras1 done')
